import bpy
ns=bpy.app.driver_namespace['art']
exec('''
import bmesh
from mathutils.geometry import tessellate_polygon
def adaptive(a,b,c,vs,fs):
    lengths=[(a-b).length,(b-c).length,(c-a).length]
    k=lengths.index(max(lengths))
    if max(lengths)>3.5:
        if k==0:
            m=(a+b)/2; adaptive(a,m,c,vs,fs); adaptive(m,b,c,vs,fs)
        elif k==1:
            m=(b+c)/2; adaptive(a,b,m,vs,fs); adaptive(a,m,c,vs,fs)
        else:
            m=(c+a)/2; adaptive(a,b,m,vs,fs); adaptive(m,b,c,vs,fs)
    else:
        j=len(vs); vs.extend([globe(p.x,p.y,R+.025) for p in [a,b,c]]); fs.append((j,j+1,j+2))
for name,coords in continents.items():
    vs=[]; fs=[]; vv=[Vector((x,y,0)) for x,y in coords]
    for tri in tessellate_polygon([vv]): adaptive(*(vv[i] for i in tri),vs,fs)
    me=bpy.data.meshes.new(name+' | refined'); me.from_pydata(vs,[],fs); me.update()
    bm=bmesh.new(); bm.from_mesh(me); bmesh.ops.remove_doubles(bm,verts=list(bm.verts),dist=.00001); bmesh.ops.recalc_face_normals(bm,faces=list(bm.faces)); bm.to_mesh(me); bm.free(); me.update()
    ob=bpy.data.objects['Porcelain relief | '+name]; old=ob.data; ob.data=me; bpy.data.meshes.remove(old); assign(ob,mats['land']); smooth(ob)
    normals=[tuple((v.co-C).normalized()) for v in me.vertices]
    me.normals_split_custom_set_from_vertices(normals)
''',ns)
